package solution

import (
	"errors"
	"sort"
	"strings"
)

var ErrInvalidRequest = errors.New("invalid request")
var ErrCursorNotFound = errors.New("cursor not found")
var ErrBudgetExceeded = errors.New("scan budget exceeded")

type Article struct {
	Key      string
	Writer   string
	Headline string
	Link     string
	Priority int
}

type PageRequest struct {
	Account    string
	Cursor     string
	Limit      int
	ScanBudget int
}

type TraceRecord struct {
	Name     string
	Scanned  int
	Returned int
}

type PageResult struct {
	Items      []Article
	NextCursor string
	Trace      TraceRecord
}

type Queue struct {
	articles []Article
	maxPage  int
	indexes  map[string]int
}

func NewQueue(articles []Article, maxPage int) (*Queue, error) {
	if maxPage <= 0 {
		return nil, ErrInvalidRequest
	}

	copied := append([]Article(nil), articles...)
	seen := make(map[string]struct{}, len(copied))
	for _, article := range copied {
		if strings.TrimSpace(article.Key) == "" {
			return nil, ErrInvalidRequest
		}
		if _, exists := seen[article.Key]; exists {
			return nil, ErrInvalidRequest
		}
		seen[article.Key] = struct{}{}
	}

	sort.Slice(copied, func(i, j int) bool {
		if copied[i].Priority != copied[j].Priority {
			return copied[i].Priority > copied[j].Priority
		}
		return copied[i].Key < copied[j].Key
	})

	indexes := make(map[string]int, len(copied))
	for i, article := range copied {
		indexes[article.Key] = i
	}

	return &Queue{articles: copied, maxPage: maxPage, indexes: indexes}, nil
}

func (q *Queue) NextPage(request PageRequest) (PageResult, error) {
	if q == nil || strings.TrimSpace(request.Account) == "" || request.Limit < 1 || request.Limit > q.maxPage {
		return PageResult{}, ErrInvalidRequest
	}
	if request.ScanBudget < request.Limit {
		return PageResult{}, ErrBudgetExceeded
	}

	start := 0
	if request.Cursor != "" {
		index, exists := q.indexes[request.Cursor]
		if !exists {
			return PageResult{}, ErrCursorNotFound
		}
		start = index + 1
	}

	count := request.Limit
	remaining := len(q.articles) - start
	if count > remaining {
		count = remaining
	}
	end := start + count
	items := append([]Article(nil), q.articles[start:end]...)
	result := PageResult{
		Items: items,
		Trace: TraceRecord{
			Name:     "queue.next",
			Scanned:  len(items),
			Returned: len(items),
		},
	}
	if len(items) > 0 && end < len(q.articles) {
		result.NextCursor = items[len(items)-1].Key
	}
	return result, nil
}

