import "errors"

func RunWeighted(attempts int, initialWeight int, action func(weight int) error) ([]int, error) {
	if attempts <= 0 {
		return nil, errors.New("attempts must be positive")
	}
	if initialWeight <= 0 {
		return nil, errors.New("initial weight must be positive")
	}
	if action == nil {
		return nil, errors.New("action must not be nil")
	}

	used := make([]int, 0)
	weight := initialWeight
	maxInt := int(^uint(0) >> 1)
	var lastErr error

	for i := 0; i < attempts; i++ {
		used = append(used, weight)
		lastErr = action(weight)
		if lastErr == nil {
			return used, nil
		}
		if weight > maxInt/2 {
			weight = maxInt
		} else {
			weight *= 2
		}
	}
	return used, lastErr
}

package solution

import (
	"errors"
	"sort"
	"strings"
)

var ErrInvalidNote = errors.New("invalid note")
var ErrNoteNotFound = errors.New("note not found")
var ErrInvalidPage = errors.New("invalid page")

type Note struct {
	ID    int
	Topic string
	Text  string
}

type NoteStore struct {
	nextID int
	notes  map[int]Note
}

func NewNoteStore() *NoteStore {
	return &NoteStore{nextID: 1, notes: make(map[int]Note)}
}

func (s *NoteStore) Create(topic, text string) (Note, error) {
	if !validNoteFields(topic, text) {
		return Note{}, ErrInvalidNote
	}
	note := Note{ID: s.nextID, Topic: topic, Text: text}
	s.notes[note.ID] = note
	s.nextID++
	return note, nil
}

func (s *NoteStore) Update(id int, topic, text string) (Note, error) {
	if id <= 0 || !validNoteFields(topic, text) {
		return Note{}, ErrInvalidNote
	}
	if _, exists := s.notes[id]; !exists {
		return Note{}, ErrNoteNotFound
	}
	note := Note{ID: id, Topic: topic, Text: text}
	s.notes[id] = note
	return note, nil
}

func (s *NoteStore) Delete(id int) error {
	if id <= 0 {
		return ErrInvalidNote
	}
	if _, exists := s.notes[id]; !exists {
		return ErrNoteNotFound
	}
	delete(s.notes, id)
	return nil
}

func (s *NoteStore) DeleteMany(ids []int) error {
	for _, id := range ids {
		if id <= 0 {
			return ErrInvalidNote
		}
	}
	for _, id := range ids {
		if _, exists := s.notes[id]; !exists {
			return ErrNoteNotFound
		}
	}
	for _, id := range ids {
		delete(s.notes, id)
	}
	return nil
}

func (s *NoteStore) Get(id int) (Note, error) {
	if id <= 0 {
		return Note{}, ErrInvalidNote
	}
	note, exists := s.notes[id]
	if !exists {
		return Note{}, ErrNoteNotFound
	}
	return note, nil
}

func (s *NoteStore) List(topic string, offset, limit int) ([]Note, error) {
	if offset < 0 || limit < 1 || limit > 100 {
		return nil, ErrInvalidPage
	}
	matches := make([]Note, 0)
	for _, note := range s.notes {
		if topic == "" || note.Topic == topic {
			matches = append(matches, note)
		}
	}
	sort.Slice(matches, func(a, b int) bool {
		return matches[a].ID < matches[b].ID
	})
	if offset >= len(matches) {
		return []Note{}, nil
	}
	end := offset + limit
	if end > len(matches) {
		end = len(matches)
	}
	return matches[offset:end], nil
}

func validNoteFields(topic, text string) bool {
	return topic != "" && len(topic) <= 40 && strings.TrimSpace(topic) == topic &&
		text != "" && len(text) <= 500 && strings.TrimSpace(text) == text
}

package solution

import (
	"errors"
	"sort"
	"strings"
	"sync"
)

type ClusterRecord struct {
	Namespace string
	Name      string
	Replicas  int
}

type recordKey struct {
	namespace string
	name      string
}

type Reconciler struct {
	mu      sync.RWMutex
	all     bool
	leader  bool
	watched map[string]struct{}
	records map[recordKey]ClusterRecord
}

func NewReconciler(watch string, leader bool) (*Reconciler, error) {
	r := &Reconciler{
		leader:  leader,
		watched: make(map[string]struct{}),
		records: make(map[recordKey]ClusterRecord),
	}
	if watch == "" {
		r.all = true
		return r, nil
	}
	for _, part := range strings.Split(watch, ",") {
		name := strings.TrimSpace(part)
		if name == "" {
			return nil, errors.New("watch contains an empty namespace")
		}
		r.watched[name] = struct{}{}
	}
	return r, nil
}

func (r *Reconciler) Apply(record ClusterRecord, deleted bool) (bool, error) {
	if record.Namespace == "" || record.Name == "" {
		return false, errors.New("namespace and name are required")
	}
	if record.Replicas < 0 {
		return false, errors.New("replicas cannot be negative")
	}

	r.mu.Lock()
	defer r.mu.Unlock()
	if !r.leader {
		return false, errors.New("reconciler is not the leader")
	}
	if !r.all {
		if _, ok := r.watched[record.Namespace]; !ok {
			return false, nil
		}
	}
	key := recordKey{namespace: record.Namespace, name: record.Name}
	if deleted {
		delete(r.records, key)
	} else {
		r.records[key] = record
	}
	return true, nil
}

func (r *Reconciler) Snapshot() []ClusterRecord {
	r.mu.RLock()
	out := make([]ClusterRecord, 0, len(r.records))
	for _, record := range r.records {
		out = append(out, record)
	}
	r.mu.RUnlock()
	sort.Slice(out, func(i, j int) bool {
		if out[i].Namespace != out[j].Namespace {
			return out[i].Namespace < out[j].Namespace
		}
		return out[i].Name < out[j].Name
	})
	return out
}

package solution

import (
	"errors"
	"fmt"
	"strings"
)

type Step struct {
	Name     string
	Requires []string
}

type StepOutcome struct {
	Name   string
	Status string
	Error  string
}

func RunPlan(steps []Step, execute func(string) error) ([]StepOutcome, error) {
	if execute == nil {
		return nil, errors.New("execute function is nil")
	}
	indexes := make(map[string]int, len(steps))
	for i, step := range steps {
		if step.Name == "" || strings.TrimSpace(step.Name) != step.Name {
			return nil, fmt.Errorf("invalid step name at index %d", i)
		}
		if _, exists := indexes[step.Name]; exists {
			return nil, fmt.Errorf("duplicate step %q", step.Name)
		}
		indexes[step.Name] = i
	}
	for _, step := range steps {
		seen := make(map[string]bool, len(step.Requires))
		for _, dependency := range step.Requires {
			if dependency == "" || strings.TrimSpace(dependency) != dependency {
				return nil, fmt.Errorf("invalid dependency of %q", step.Name)
			}
			if seen[dependency] {
				return nil, fmt.Errorf("duplicate dependency %q of %q", dependency, step.Name)
			}
			seen[dependency] = true
			if dependency == step.Name {
				return nil, fmt.Errorf("step %q depends on itself", step.Name)
			}
			if _, exists := indexes[dependency]; !exists {
				return nil, fmt.Errorf("unknown dependency %q of %q", dependency, step.Name)
			}
		}
	}
	colors := make(map[string]uint8, len(steps))
	var visit func(string) error
	visit = func(name string) error {
		if colors[name] == 1 {
			return fmt.Errorf("dependency cycle involving %q", name)
		}
		if colors[name] == 2 {
			return nil
		}
		colors[name] = 1
		for _, dependency := range steps[indexes[name]].Requires {
			if err := visit(dependency); err != nil {
				return err
			}
		}
		colors[name] = 2
		return nil
	}
	for _, step := range steps {
		if err := visit(step.Name); err != nil {
			return nil, err
		}
	}

	outcomes := make([]StepOutcome, 0, len(steps))
	status := make(map[string]string, len(steps))
	for len(outcomes) < len(steps) {
		progress := false
		for _, step := range steps {
			if status[step.Name] != "" {
				continue
			}
			blocked := false
			ready := true
			for _, dependency := range step.Requires {
				dependencyStatus := status[dependency]
				if dependencyStatus == "failed" || dependencyStatus == "skipped" {
					blocked = true
					break
				}
				if dependencyStatus != "succeeded" {
					ready = false
				}
			}
			if blocked {
				status[step.Name] = "skipped"
				outcomes = append(outcomes, StepOutcome{Name: step.Name, Status: "skipped"})
				progress = true
				break
			}
			if !ready {
				continue
			}
			outcome := StepOutcome{Name: step.Name, Status: "succeeded"}
			if err := execute(step.Name); err != nil {
				outcome.Status = "failed"
				outcome.Error = err.Error()
			}
			status[step.Name] = outcome.Status
			outcomes = append(outcomes, outcome)
			progress = true
			break
		}
		if !progress {
			return nil, errors.New("validated plan could not make progress")
		}
	}
	return outcomes, nil
}

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public final class Solution {
    private Solution() {}

    public static List<String> transformCatalog(List<String> lines, int batchSize) {
        if (lines == null || batchSize <= 0) {
            throw new IllegalArgumentException("arguments");
        }
        if (lines.isEmpty()) {
            return List.of();
        }
        if (!"sku|title|section".equals(lines.get(0))) {
            throw new IllegalArgumentException("header");
        }

        List<String> result = new ArrayList<>(lines.size());
        result.add("sku|title|section");
        int start = 1;
        while (start < lines.size()) {
            int end = start + Math.min(batchSize, lines.size() - start);
            for (int i = start; i < end; i++) {
                String line = lines.get(i);
                if (line == null) {
                    throw new IllegalArgumentException("null line");
                }
                String[] fields = line.split("\\|", -1);
                if (fields.length != 3) {
                    throw new IllegalArgumentException("record " + i);
                }
                for (int j = 0; j < fields.length; j++) {
                    fields[j] = fields[j].trim();
                    if (fields[j].isEmpty()) {
                        throw new IllegalArgumentException("record " + i);
                    }
                }
                result.add(fields[0] + "|"
                        + fields[1].toUpperCase(Locale.ROOT) + "|" + fields[2]);
            }
            start = end;
        }
        return List.copyOf(result);
    }
}

import java.util.List;
import java.util.Locale;

public final class Solution {
    private Solution() {}

    public interface TextConversion {
        boolean supports(String mediaType, Class<?> targetType);
        Object convert(String body);
    }

    public static final class ParseException extends Exception {
        public ParseException(String message) {
            super(message);
        }

        public ParseException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    public static Object parse(String body, String contentType, Class<?> targetType,
                               List<TextConversion> conversions) throws ParseException {
        if (body == null || contentType == null || targetType == null || conversions == null) {
            throw new IllegalArgumentException("arguments must not be null");
        }
        for (TextConversion conversion : conversions) {
            if (conversion == null) {
                throw new IllegalArgumentException("conversion must not be null");
            }
        }

        String mediaType = normalize(contentType);
        for (TextConversion conversion : conversions) {
            try {
                if (conversion.supports(mediaType, targetType)) {
                    Object value = conversion.convert(body);
                    if (value != null && !targetType.isInstance(value)) {
                        throw new ParseException("conversion returned the wrong type");
                    }
                    return value;
                }
            } catch (ParseException exception) {
                throw exception;
            } catch (RuntimeException exception) {
                throw new ParseException("custom conversion failed", exception);
            }
        }

        try {
            if (mediaType.equals("text/plain") && targetType == String.class) {
                return body;
            }
            if (mediaType.equals("application/integer") && targetType == Integer.class) {
                return Integer.valueOf(body.trim());
            }
            if (mediaType.equals("application/boolean") && targetType == Boolean.class) {
                String value = body.trim();
                if (value.equalsIgnoreCase("true")) return Boolean.TRUE;
                if (value.equalsIgnoreCase("false")) return Boolean.FALSE;
                throw new IllegalArgumentException("invalid boolean");
            }
        } catch (RuntimeException exception) {
            throw new ParseException("built-in conversion failed", exception);
        }
        throw new ParseException("unsupported conversion");
    }

    private static String normalize(String contentType) {
        int semicolon = contentType.indexOf(';');
        String value = semicolon < 0
                ? contentType
                : contentType.substring(0, semicolon);
        return value.trim().toLowerCase(Locale.ROOT);
    }
}

