    public static final class Product {
        private final String code;
        private final String url;

        private Product(String code, String url) {
            this.code = code;
            this.url = url;
        }

        public String getCode() {
            return code;
        }

        public String getUrl() {
            return url;
        }
    }

    public static final class Catalog {
        private final Map<String, String> data;

        private Catalog(Map<String, String> data) {
            this.data = Collections.unmodifiableMap(new HashMap<>(data));
        }
    }

    public static Catalog emptyCatalog() {
        return new Catalog(Collections.emptyMap());
    }

    public static Catalog add(Catalog catalog, String code, String url) {
        check(catalog, code, url);
        if (catalog.data.containsKey(code)) {
            throw new IllegalArgumentException();
        }
        Map<String, String> data = new HashMap<>(catalog.data);
        data.put(code, url);
        return new Catalog(data);
    }

    public static Catalog remove(Catalog catalog, String code) {
        checkCode(catalog, code);
        if (!catalog.data.containsKey(code)) {
            throw new IllegalArgumentException();
        }
        Map<String, String> data = new HashMap<>(catalog.data);
        data.remove(code);
        return new Catalog(data);
    }

    public static Catalog changeUrl(Catalog catalog, String code, String url) {
        check(catalog, code, url);
        if (!catalog.data.containsKey(code)) {
            throw new IllegalArgumentException();
        }
        Map<String, String> data = new HashMap<>(catalog.data);
        data.put(code, url);
        return new Catalog(data);
    }

    public static String urlOf(Catalog catalog, String code) {
        checkCode(catalog, code);
        return catalog.data.get(code);
    }

    public static List<Product> list(Catalog catalog) {
        if (catalog == null) {
            throw new IllegalArgumentException();
        }
        List<String> codes = new ArrayList<>(catalog.data.keySet());
        Collections.sort(codes);
        List<Product> products = new ArrayList<>(codes.size());
        for (String code : codes) {
            products.add(new Product(code, catalog.data.get(code)));
        }
        return Collections.unmodifiableList(products);
    }

    private static void check(Catalog catalog, String code, String url) {
        checkCode(catalog, code);
        if (url == null || url.isEmpty()) {
            throw new IllegalArgumentException();
        }
    }

    private static void checkCode(Catalog catalog, String code) {
        if (catalog == null || code == null || code.isEmpty()) {
            throw new IllegalArgumentException();
        }
    }
}

public final class Solution {
    private Solution() {}

    public enum PayloadKind { TEXT, IMAGE, SOUND }
    public enum DeliveryState { NEW, SENDING, DELIVERED, FAILED }

    public static final class Note {
        private final String id;
        private final long timestamp;
        private final String sender;
        private final PayloadKind kind;
        private final String content;
        private DeliveryState state = DeliveryState.NEW;
        private boolean read;

        public Note(String id, long timestamp, String sender,
                    PayloadKind kind, String content) {
            if (id == null || id.isBlank() || timestamp < 0
                    || sender == null || sender.isBlank()
                    || kind == null || content == null) {
                throw new IllegalArgumentException();
            }
            this.id = id.trim();
            this.timestamp = timestamp;
            this.sender = sender.trim();
            this.kind = kind;
            this.content = content;
        }

        public String id() { return id; }
        public long timestamp() { return timestamp; }
        public String sender() { return sender; }
        public PayloadKind kind() { return kind; }
        public String content() { return content; }
        public synchronized DeliveryState state() { return state; }
        public synchronized boolean isRead() { return read; }

        public synchronized boolean beginSend() {
            if (state != DeliveryState.NEW) return false;
            state = DeliveryState.SENDING;
            return true;
        }

        public synchronized boolean deliver() {
            if (state != DeliveryState.SENDING) return false;
            state = DeliveryState.DELIVERED;
            return true;
        }

        public synchronized boolean fail() {
            if (state != DeliveryState.NEW && state != DeliveryState.SENDING) {
                return false;
            }
            state = DeliveryState.FAILED;
            return true;
        }

        public synchronized boolean markRead() {
            if (state != DeliveryState.DELIVERED || read) return false;
            read = true;
            return true;
        }

        @Override
        public synchronized String toString() {
            return kind + "|" + content + "|" + sender + "|"
                    + state + "|read=" + read;
        }
    }
}

