def _descriptor(data, scheme):
    if scheme == "sample2":
        return tuple(data[::2])
    if scheme == "pair_sum":
        result = []
        for index in range(0, len(data), 2):
            if index + 1 < len(data):
                result.append((data[index] + data[index + 1]) % 256)
            else:
                result.append(data[index])
        return tuple(result)
    if scheme == "run_length":
        if not data:
            return ()
        result = []
        length = 1
        for index in range(1, len(data)):
            if data[index] == data[index - 1]:
                length += 1
            else:
                result.append(length)
                length = 1
        result.append(length)
        return tuple(result)
    result = []
    for start in range(0, len(data), 4):
        value = 0
        for byte in data[start:start + 4]:
            value ^= byte
        result.append(value)
    return tuple(result)


def compile_catalog(batches, schemes):
    if not isinstance(batches, Mapping):
        raise TypeError("batches must be a mapping")

    allowed = {"sample2", "pair_sum", "run_length", "xor4"}
    ordered_schemes = []
    seen = set()
    for scheme in schemes:
        if not isinstance(scheme, str):
            raise TypeError("scheme names must be strings")
        if scheme not in allowed:
            raise ValueError("unknown scheme: " + scheme)
        if scheme not in seen:
            seen.add(scheme)
            ordered_schemes.append(scheme)

    materialized = {}
    for batch_name, records in batches.items():
        copied_records = []
        for record in records:
            if not isinstance(record, (tuple, list)) or len(record) != 2:
                raise TypeError("records must be name-payload pairs")
            name, payload = record
            if not isinstance(name, str) or not name:
                raise ValueError("record names must be non-empty strings")
            try:
                view = memoryview(payload)
            except TypeError as exc:
                raise TypeError("payload must support the buffer protocol") from exc
            if view.itemsize != 1:
                raise ValueError("payload elements must be one byte wide")
            copied_records.append((name, bytes(view)))
        materialized[batch_name] = copied_records

    output = {}
    for batch_name, records in materialized.items():
        by_scheme = {}
        for scheme in ordered_schemes:
            descriptors = {}
            for name, data in records:
                descriptors[name] = _descriptor(data, scheme)
            by_scheme[scheme] = descriptors
        output[batch_name] = by_scheme
    return output

