use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Tool { pub id: u64, pub name: String, pub zone: String }
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub struct Workshop {
    pub name: String,
    pub zones: BTreeMap<String, Vec<u64>>,
    pub tools: BTreeMap<u64, Tool>,
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Command {
    Health, Summary, Zone(String), AddZone(String), RemoveZone(String),
    Tool(u64), AddTool { id: u64, name: String, zone: String }, RemoveTool(u64),
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Reply { Text(String), Changed, NotFound, Conflict, Invalid }

pub fn dispatch(workshop: &mut Workshop, command: Command) -> Reply {
    match command {
        Command::Health => Reply::Text("ready".into()),
        Command::Summary => Reply::Text(format!(
            "{}|{}",
            workshop.name,
            workshop.zones.keys().cloned().collect::<Vec<_>>().join(",")
        )),
        Command::Zone(zone) => {
            let zone = zone.trim();
            if zone.is_empty() {
                Reply::Invalid
            } else {
                match workshop.zones.get(zone) {
                    Some(ids) => Reply::Text(
                        ids.iter().map(u64::to_string).collect::<Vec<_>>().join(",")
                    ),
                    None => Reply::NotFound,
                }
            }
        }
        Command::AddZone(zone) => {
            let zone = zone.trim();
            if zone.is_empty() {
                Reply::Invalid
            } else if workshop.zones.contains_key(zone) {
                Reply::Conflict
            } else {
                workshop.zones.insert(zone.into(), Vec::new());
                Reply::Changed
            }
        }
        Command::RemoveZone(zone) => {
            let zone = zone.trim();
            if zone.is_empty() {
                return Reply::Invalid;
            }
            let Some(ids) = workshop.zones.remove(zone) else {
                return Reply::NotFound;
            };
            for id in ids {
                workshop.tools.remove(&id);
            }
            Reply::Changed
        }
        Command::Tool(id) => match workshop.tools.get(&id) {
            Some(tool) => Reply::Text(format!("{}|{}|{}", tool.id, tool.name, tool.zone)),
            None => Reply::NotFound,
        },
        Command::AddTool { id, name, zone } => {
            let name = name.trim();
            let zone = zone.trim();
            if name.is_empty() || zone.is_empty() {
                return Reply::Invalid;
            }
            if workshop.tools.contains_key(&id) {
                return Reply::Conflict;
            }
            let Some(ids) = workshop.zones.get_mut(zone) else {
                return Reply::NotFound;
            };
            ids.push(id);
            workshop.tools.insert(id, Tool {
                id,
                name: name.into(),
                zone: zone.into(),
            });
            Reply::Changed
        }
        Command::RemoveTool(id) => {
            let Some(tool) = workshop.tools.remove(&id) else {
                return Reply::NotFound;
            };
            if let Some(ids) = workshop.zones.get_mut(&tool.zone) {
                ids.retain(|stored| *stored != id);
            }
            Reply::Changed
        }
    }
}

use std::collections::HashSet;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecordFormat {
    Lines,
    Bracketed,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TranscodeError {
    Malformed,
    DuplicateKey,
    InvalidUtf8,
}

fn valid_key(key: &str) -> bool {
    !key.is_empty() && key.bytes().all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn decode(value: &str) -> Result<String, TranscodeError> {
    let bytes = value.as_bytes();
    let mut output = Vec::new();
    let mut index = 0;

    while index < bytes.len() {
        let byte = bytes[index];
        if byte == b'%' {
            if index + 2 >= bytes.len() {
                return Err(TranscodeError::Malformed);
            }
            let high = hex_value(bytes[index + 1]).ok_or(TranscodeError::Malformed)?;
            let low = hex_value(bytes[index + 2]).ok_or(TranscodeError::Malformed)?;
            output.push((high << 4) | low);
            index += 3;
        } else if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            output.push(byte);
            index += 1;
        } else {
            return Err(TranscodeError::Malformed);
        }
    }

    String::from_utf8(output).map_err(|_| TranscodeError::InvalidUtf8)
}

fn encode(value: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut output = String::new();

    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            output.push(char::from(byte));
        } else {
            output.push('%');
            output.push(char::from(HEX[(byte >> 4) as usize]));
            output.push(char::from(HEX[(byte & 0x0f) as usize]));
        }
    }

    output
}

fn parse_record(record: &str) -> Result<(String, String), TranscodeError> {
    let (key, value) = record.split_once('=').ok_or(TranscodeError::Malformed)?;
    if !valid_key(key) || value.contains('=') {
        return Err(TranscodeError::Malformed);
    }
    Ok((key.to_owned(), decode(value)?))
}

fn trim_ascii_whitespace(value: &str) -> &str {
    value.trim_matches(|ch: char| ch.is_ascii_whitespace())
}

pub fn transcode_records(
    input: &str,
    from: RecordFormat,
    to: RecordFormat,
    compact: bool,
) -> Result<String, TranscodeError> {
    let mut records = Vec::new();

    match from {
        RecordFormat::Lines => {
            if input.contains('\r') || input == "\n" {
                return Err(TranscodeError::Malformed);
            }

            let body = input.strip_suffix('\n').unwrap_or(input);
            if !body.is_empty() {
                for record in body.split('\n') {
                    if record.is_empty() {
                        return Err(TranscodeError::Malformed);
                    }
                    records.push(parse_record(record)?);
                }
            }
        }
        RecordFormat::Bracketed => {
            let trimmed = trim_ascii_whitespace(input);
            if trimmed.len() < 2 || !trimmed.starts_with('[') || !trimmed.ends_with(']') {
                return Err(TranscodeError::Malformed);
            }

            let inner = trim_ascii_whitespace(&trimmed[1..trimmed.len() - 1]);
            if !inner.is_empty() {
                for part in inner.split(',') {
                    let record = trim_ascii_whitespace(part);
                    if record.is_empty() {
                        return Err(TranscodeError::Malformed);
                    }
                    records.push(parse_record(record)?);
                }
            }
        }
    }

    let mut seen = HashSet::new();
    for (key, _) in &records {
        if !seen.insert(key.clone()) {
            return Err(TranscodeError::DuplicateKey);
        }
    }

    records.sort_by(|left, right| left.0.cmp(&right.0));
    let rendered: Vec<String> = records
        .iter()
        .map(|(key, value)| format!("{}={}", key, encode(value)))
        .collect();

    Ok(match to {
        RecordFormat::Lines => {
            if rendered.is_empty() {
                String::new()
            } else {
                format!("{}\n", rendered.join("\n"))
            }
        }
        RecordFormat::Bracketed => {
            if rendered.is_empty() {
                if compact {
                    "[]".to_owned()
                } else {
                    "[ ]".to_owned()
                }
            } else if compact {
                format!("[{}]", rendered.join(","))
            } else {
                format!("[ {} ]", rendered.join(", "))
            }
        }
    })
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public final class Solution {
    private static final int[] PALETTE = {
        0xFF0000, 0xFFFF00, 0x00FF00, 0x00FFFF, 0x0000FF, 0xFF00FF
    };

    private Solution() {}

    public static int[][] visibleMarkers(int[][] spots, int viewerX, int viewerY,
                                         long maximumDistance, int fixedRgb,
                                         boolean rainbow, int phase) {
        if (spots == null || maximumDistance < 0
                || fixedRgb < 0 || fixedRgb > 0xFFFFFF) {
            throw new IllegalArgumentException("invalid argument");
        }

        int color = rainbow
                ? PALETTE[Math.floorMod(phase, PALETTE.length)]
                : fixedRgb;
        BigInteger radius = BigInteger.valueOf(maximumDistance);
        BigInteger limitSquared = radius.multiply(radius);
        List<int[]> result = new ArrayList<>();

        for (int[] spot : spots) {
            if (spot == null || spot.length != 3
                    || (spot[2] != 0 && spot[2] != 1)) {
                throw new IllegalArgumentException("malformed spot");
            }
            long dx = (long) spot[0] - viewerX;
            long dy = (long) spot[1] - viewerY;
            BigInteger bx = BigInteger.valueOf(dx);
            BigInteger by = BigInteger.valueOf(dy);
            BigInteger distanceSquared = bx.multiply(bx).add(by.multiply(by));
            if (spot[2] == 1 && distanceSquared.compareTo(limitSquared) <= 0) {
                result.add(new int[] {spot[0], spot[1], color});
            }
        }
        return result.toArray(new int[result.size()][]);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public final class Solution {
    private Solution() {}

    public static final class Asset {
        private final long id;
        private final String group;
        private final String name;

        public Asset(long id, String group, String name) {
            if (id <= 0 || group == null || group.isEmpty()
                    || name == null || name.isEmpty()) {
                throw new IllegalArgumentException();
            }
            this.id = id;
            this.group = group;
            this.name = name;
        }

        public long getId() { return id; }
        public String getGroup() { return group; }
        public String getName() { return name; }
    }

    public static List<Asset> selectAssets(List<Asset> assets, Set<String> groups) {
        validateAssets(assets);
        if (groups == null) {
            throw new IllegalArgumentException();
        }
        for (String group : groups) {
            if (group == null) {
                throw new IllegalArgumentException();
            }
        }

        List<Asset> result = new ArrayList<>();
        for (Asset asset : assets) {
            if (groups.isEmpty() || groups.contains(asset.getGroup())) {
                result.add(asset);
            }
        }
        return result;
    }

    public static Asset findAsset(List<Asset> assets, long id) {
        validateAssets(assets);
        if (id <= 0) {
            throw new IllegalArgumentException();
        }
        for (Asset asset : assets) {
            if (asset.getId() == id) {
                return asset;
            }
        }
        return null;
    }

    private static void validateAssets(List<Asset> assets) {
        if (assets == null) {
            throw new IllegalArgumentException();
        }
        for (Asset asset : assets) {
            if (asset == null) {
                throw new IllegalArgumentException();
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public final class Solution {
    private Solution() {}

    public enum Kind { CREATE, REPLACE, DELETE }

    public static final class Change {
        private final Kind kind;
        private final int groupId;
        private final List<Integer> permissionIds;

        public Change(Kind kind, int groupId, Collection<Integer> permissionIds) {
            if (kind == null || groupId <= 0) {
                throw new IllegalArgumentException("invalid change");
            }
            if (permissionIds == null && kind != Kind.DELETE) {
                throw new IllegalArgumentException("permissions must not be null");
            }
            this.kind = kind;
            this.groupId = groupId;
            this.permissionIds = permissionIds == null
                    ? Collections.emptyList()
                    : new ArrayList<>(permissionIds);
        }
    }

    public static Map<Integer, Set<Integer>> apply(
            Map<Integer, ? extends Collection<Integer>> initial,
            List<Change> changes) {
        if (initial == null || changes == null) {
            throw new IllegalArgumentException("inputs must not be null");
        }

        TreeMap<Integer, TreeSet<Integer>> working = new TreeMap<>();
        for (Map.Entry<Integer, ? extends Collection<Integer>> entry : initial.entrySet()) {
            Integer id = entry.getKey();
            if (id == null || id <= 0 || entry.getValue() == null) {
                throw new IllegalArgumentException("invalid initial group");
            }
            working.put(id, checkedSet(entry.getValue()));
        }

        for (Change change : changes) {
            if (change == null) {
                throw new IllegalArgumentException("null change");
            }
            boolean exists = working.containsKey(change.groupId);
            TreeSet<Integer> permissions = checkedSet(change.permissionIds);
            if (change.kind == Kind.CREATE) {
                if (exists) {
                    throw new IllegalArgumentException("group already exists");
                }
                working.put(change.groupId, permissions);
            } else if (change.kind == Kind.REPLACE) {
                if (!exists) {
                    throw new IllegalArgumentException("group does not exist");
                }
                working.put(change.groupId, permissions);
            } else {
                if (!exists) {
                    throw new IllegalArgumentException("group does not exist");
                }
                working.remove(change.groupId);
            }
        }

        Map<Integer, Set<Integer>> result = new TreeMap<>();
        for (Map.Entry<Integer, TreeSet<Integer>> entry : working.entrySet()) {
            result.put(entry.getKey(),
                    Collections.unmodifiableSet(new TreeSet<>(entry.getValue())));
        }
        return Collections.unmodifiableMap(result);
    }

    private static TreeSet<Integer> checkedSet(Collection<Integer> values) {
        TreeSet<Integer> set = new TreeSet<>();
        for (Integer value : values) {
            if (value == null || value <= 0) {
                throw new IllegalArgumentException("invalid permission ID");
            }
            set.add(value);
        }
        return set;
    }
}

import java.util.ArrayList;
import java.util.List;

public final class Solution {
    private Solution() {}

    public record Clip(String title, String url) {}

    public static List<Clip> decodeFeed(String payload) {
        if (payload == null) {
            throw new IllegalArgumentException("payload");
        }
        if (payload.isEmpty()) {
            return List.of();
        }
        if (payload.indexOf('\r') >= 0) {
            throw new IllegalArgumentException("carriage return");
        }

        String body = payload.endsWith("\n")
                ? payload.substring(0, payload.length() - 1)
                : payload;
        if (body.isEmpty()) {
            throw new IllegalArgumentException("blank line");
        }

        List<Clip> result = new ArrayList<>();
        for (String line : body.split("\n", -1)) {
            int separator = line.indexOf('|');
            if (separator <= 0
                    || separator != line.lastIndexOf('|')
                    || separator == line.length() - 1) {
                throw new IllegalArgumentException("line");
            }
            String title = line.substring(0, separator);
            String url = line.substring(separator + 1);
            if (!title.equals(title.strip()) || !url.equals(url.strip())) {
                throw new IllegalArgumentException("whitespace");
            }
            result.add(new Clip(title, url));
        }
        return List.copyOf(result);
    }
}
